/*
 * 이름 글꼴 맞추기
 * 기본 글꼴(Do Hyeon)에는 자주 쓰는 한글 2,437자만 들어 있어요. '옝·쀏·똠'처럼 드문 글자가 섞인 이름은
 * 그 글자만 다른 글꼴로 보여서 어색해요. 그런 이름은 통째로 한글 11,172자가 다 있는 도트 글꼴(Galmuri11)로 보여 줘요.
 */
const Glyph = (() => {
  const BITS = (() => {
    const s = atob('');
    const a = new Uint8Array(s.length);
    for (let i = 0; i < s.length; i++) a[i] = s.charCodeAt(i);
    return a;
  })();
  function ok(str) {
    for (const ch of String(str || '')) {
      const c = ch.codePointAt(0);
      if (c >= 0xac00 && c <= 0xd7a3) {
        const i = c - 0xac00;
        if (!(BITS[i >> 3] & (1 << (i & 7)))) return false;
      } else if (c >= 0x3131 && c <= 0x318e) {
        // 자음·모음 낱자는 들어 있어요
      } else if (c > 0x7e) {
        return false;
      }
    }
    return true;
  }
  // 이름 칸에 붙여요: 기본 글꼴에 없는 글자가 있으면 도트 글꼴로
  function fit(el, str) {
    if (el) el.classList.toggle('nm-px', !ok(str));
    return el;
  }
  return { ok, fit };
})();
